import type { Group } from 'three';
import { MeshoptDecoder } from 'three/addons/libs/meshopt_decoder.module.js';
import { type GLTF, GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { LoadProgress } from './loadProgress';
import assetSizes from './roomAssetSizes.json';

/**
 * The runtime files generated by tools/room/. The size table is bundled at build time
 * so progress weights follow each asset revision without an extra network request.
 */
const ROOM_FILES = {
  room: 'room.glb',
  tv: 'tv-high.glb',
  pc: 'pc-base.glb',
  radio: 'radio-base.glb',
  ps2: 'ps2-base.glb',
} as const;

type RoomFileKey = keyof typeof ROOM_FILES;

export interface RoomAssets {
  /** The loader the room was read with (meshopt ready), for the files the room fetches later. */
  readonly loader: GLTFLoader;
  /** Baked, unlit environment (walls, furniture, posters) plus the lava animation clip. */
  readonly room: GLTF;
  /** The CRT television at close-up detail; holds the replaceable screen mesh. */
  readonly tv: Group;
  /** Devices baked with the same lighting as their surroundings (PC, radio, PS2). */
  readonly devices: readonly Group[];
}

export async function loadRoomAssets(baseUrl: string, onProgress: (fraction: number) => void): Promise<RoomAssets> {
  const loader = new GLTFLoader().setMeshoptDecoder(MeshoptDecoder);
  const expected = Object.fromEntries(Object.entries(ROOM_FILES).map(([key, file]) => [key, assetSizes[file]]));
  const progress = new LoadProgress(expected, onProgress);

  const load = async (key: RoomFileKey): Promise<GLTF> => {
    const gltf = await loader.loadAsync(new URL(ROOM_FILES[key], baseUrl).href, (event) => {
      progress.update(key, event.loaded, event.lengthComputable ? event.total : undefined);
    });
    progress.complete(key);
    return gltf;
  };

  const [room, tv, pc, radio, ps2] = await Promise.all([
    load('room'),
    load('tv'),
    load('pc'),
    load('radio'),
    load('ps2'),
  ]);
  return { loader, room, tv: tv.scene, devices: [pc.scene, radio.scene, ps2.scene] };
}
